UPDATE async_task SET locked_until = #{lockedUntil}, updated_at = #{now}
WHERE id = #{id} AND status = 'RUNNING' AND locked_by = #{workerId}
  AND locked_until > #{now}

UPDATE async_task
SET status = 'SUCCEEDED', next_run_at = #{now}, locked_by = NULL, locked_until = NULL,
    last_error_code = NULL, last_error_message = NULL, finished_at = #{now}, updated_at = #{now}
WHERE id = #{id} AND status = 'RUNNING' AND locked_by = #{workerId}
  AND locked_until > #{now}

UPDATE async_task
SET status = #{status}, next_run_at = #{nextRunAt}, locked_by = NULL, locked_until = NULL,
    last_error_code = #{errorCode}, last_error_message = #{errorMessage},
    finished_at = #{finishedAt}, updated_at = #{now}
WHERE id = #{id} AND status = 'RUNNING' AND locked_by = #{workerId}
  AND locked_until > #{now}
